const long double EPS = 1e-10L;

struct Point {
    long double x, y;

    Point operator+(const Point& other) const {
        return {x + other.x, y + other.y};
    }

    Point operator-(const Point& other) const {
        return {x - other.x, y - other.y};
    }

    Point operator*(long double k) const {
        return {x * k, y * k};
    }
};

long double cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

int sign(long double value) {
    if (value > EPS) return 1;
    if (value < -EPS) return -1;
    return 0;
}

bool onSegment(const Point& p, const Point& a, const Point& b) {
    if (sign(cross(p - a, b - a)) != 0) return false;
    return p.x >= std::min(a.x, b.x) - EPS &&
           p.x <= std::max(a.x, b.x) + EPS &&
           p.y >= std::min(a.y, b.y) - EPS &&
           p.y <= std::max(a.y, b.y) + EPS;
}

int segmentRelation(const Point& a, const Point& b,
                    const Point& c, const Point& d) {
    int o1 = sign(cross(c - a, b - a));
    int o2 = sign(cross(d - a, b - a));
    int o3 = sign(cross(a - c, d - c));
    int o4 = sign(cross(b - c, d - c));

    if (o1 * o2 < 0 && o3 * o4 < 0) return -1;

    if ((o1 == 0 && onSegment(c, a, b)) ||
        (o2 == 0 && onSegment(d, a, b)) ||
        (o3 == 0 && onSegment(a, c, d)) ||
        (o4 == 0 && onSegment(b, c, d))) {
        return 0;
    }

    return 1;
}

int main() {
    Point v, p, w1, w2, m1, m2;

    if (scanf("%Lf%Lf", &v.x, &v.y) != 2) return 0;
    scanf("%Lf%Lf", &p.x, &p.y);
