         (v.y - m1.y) * mirrorDirection.y) / lengthSquared;

    Point foot = m1 + mirrorDirection * projection;
    Point reflected = foot * 2.0L - v;

    Point reflectedPath = p - reflected;
    long double denominator = cross(mirrorDirection, reflectedPath);

    if (std::fabs(denominator) <= EPS ||
        segmentRelation(reflected, p, m1, m2) > 0) {
        printf("NO\n");
        return 0;
    }

    long double t = cross(reflected - m1, reflectedPath) / denominator;
    Point contact = m1 + mirrorDirection * t;

    if (segmentRelation(v, contact, w1, w2) > 0 &&
        segmentRelation(contact, p, w1, w2) > 0) {
        printf("YES\n");
