};

Point V, P, W1, W2, M1, M2, C, G;

double cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

Point operator-(Point a, Point b) {
    return {a.x - b.x, a.y - b.y};
}

int sign(double value) {
    if (std::fabs(value) < eps) return 0;
    return value < 0 ? -1 : 1;
}

bool onSegment(Point a, Point b, Point p) {
    return p.x >= std::min(a.x, b.x) - eps &&
           p.x <= std::max(a.x, b.x) + eps &&
           p.y >= std::min(a.y, b.y) - eps &&
           p.y <= std::max(a.y, b.y) + eps;
}

int Cross(Point a, Point b, Point c, Point d) {
    int o1 = sign(cross(b - a, c - a));
    int o2 = sign(cross(b - a, d - a));
    int o3 = sign(cross(d - c, a - c));
    int o4 = sign(cross(d - c, b - c));

    if (o1 * o2 < 0 && o3 * o4 < 0) return -1;

    if (o1 == 0 && onSegment(a, b, c)) return 0;
    if (o2 == 0 && onSegment(a, b, d)) return 0;
    if (o3 == 0 && onSegment(c, d, a)) return 0;
    if (o4 == 0 && onSegment(c, d, b)) return 0;

    return 1;
}

bool reflectPoint() {
    Point direction = M2 - M1;
    double lengthSquared = direction.x * direction.x +
                           direction.y * direction.y;
    if (lengthSquared < eps * eps) return false;

    double t = ((V.x - M1.x) * direction.x +
                (V.y - M1.y) * direction.y) / lengthSquared;

    C = {M1.x + t * direction.x, M1.y + t * direction.y};
    G = {2.0 * C.x - V.x, 2.0 * C.y - V.y};
    return true;
}

bool intersectionPoint() {
    Point r = P - G;
    Point s = M2 - M1;
    double denominator = cross(r, s);

    if (std::fabs(denominator) < eps) return false;

    double t = cross(M1 - G, s) / denominator;
    C = {G.x + t * r.x, G.y + t * r.y};
    return true;
}

